import { Switch, useThemeType, type ThemeType } from '@gravity-ui/uikit';

export interface ThemeToggleProps {
  onThemeChange: (theme: ThemeType) => void;
}

/**
 * Переключатель светлой/тёмной темы.
 * Текущая тема читается из контекста ближайшего ThemeProvider (useThemeType),
 * а смена делегируется владельцу состояния — ThemeProvider в корне приложения.
 */
export function ThemeToggle({ onThemeChange }: ThemeToggleProps) {
  const themeType = useThemeType();

  return (
    <Switch
      checked={themeType === 'dark'}
      onUpdate={(checked) => onThemeChange(checked ? 'dark' : 'light')}
      content="Тёмная тема"
    />
  );
}
EOF
cat > src/App.tsx <<'EOF'
import { Flex, Text, type ThemeType } from '@gravity-ui/uikit';

import { ThemeToggle } from './ThemeToggle';

export interface AppProps {
  onThemeChange: (theme: ThemeType) => void;
}

export function App({ onThemeChange }: AppProps) {
  return (
    <Flex direction="column" gap={4} style={{ padding: 24 }}>
      <Text variant="header-1">Настройки</Text>
      <ThemeToggle onThemeChange={onThemeChange} />
    </Flex>
  );
}
EOF
cat > src/main.tsx <<'EOF'
// Preconfigured Gravity UI setup is ALREADY wired here (both CSS imports + ThemeProvider).
// Implement the requested feature in App.tsx (you may add sibling files).
import '@gravity-ui/uikit/styles/fonts.css';
import '@gravity-ui/uikit/styles/styles.css';

import React from 'react';
import ReactDOM from 'react-dom/client';
import { ThemeProvider, type ThemeType } from '@gravity-ui/uikit';

import { App } from './App';

// Состояние темы живёт рядом с корневым ThemeProvider: он единственный
// пишет класс темы на document.body, поэтому тема меняется для всей страницы.
function Root() {
  const [theme, setTheme] = React.useState<ThemeType>('light');

  return (
    <ThemeProvider theme={theme}>
      <App onThemeChange={setTheme} />
    </ThemeProvider>
  );
}

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <Root />
  </React.StrictMode>,
);
EOF
